      meeting_note_id: webhookBody.meeting_note_id,
      project_document_id: webhookBody.project_document_id
    }}];
  }
  return [{ json: {
    error: 'false',
    raw_content: (driveResult.data && driveResult.data.extracted_text) || '',
    file_type: webhookBody.file_type,
    client_id: webhookBody.client_id,
    project_id: webhookBody.project_id,
    meeting_note_id: webhookBody.meeting_note_id,
    project_document_id: webhookBody.project_document_id
