const currentJson = $input.first().json;

let fileType = currentJson.file_type;
let meetingNoteId = currentJson.meeting_note_id;
let projectDocId = currentJson.project_document_id;
let errorMessage = currentJson.error_message || currentJson.message || currentJson.error || 'Extraction failed';

if (!fileType) {
  try {
    const ep = $('Code: Format Extraction Prompt').first().json;
    fileType = ep.file_type;
    meetingNoteId = ep.meeting_note_id;
    projectDocId = ep.project_document_id;
  } catch(e) {
    throw new Error('Cannot determine record IDs for error handling: ' + e.message);
  }
}

const isNote = fileType === 'meeting_notes';
const recordKey = isNote ? 'meeting_note' : 'project_document';

return [{
  url_segment: isNote
    ? 'meeting_notes/' + meetingNoteId
    : 'project_documents/' + projectDocId,
  body: { [recordKey]: { status: 'extraction_failed', error_message: errorMessage } }
}];

const ep = $('Code: Format Extraction Prompt').first().json;

try {
  let llmResponse = $input.first().json.llm_response;
  if (typeof llmResponse === 'string') {
    llmResponse = JSON.parse(llmResponse);
  }
  if (!llmResponse || typeof llmResponse !== 'object') {
    throw new Error('llm_response missing or not an object');
  }
  return [{ json: {
    status: 'updating_project_memory',
    document_summary: llmResponse.document_summary || null,
    ai_observations: llmResponse.ai_observations || null,
    file_type: ep.file_type,
    meeting_note_id: ep.meeting_note_id,
    project_document_id: ep.project_document_id
  }}];
} catch(e) {
  // Throw so n8n routes to the error wire → Format Error Body → Mark Record Failed
  throw new Error('LLM response parse failed: ' + e.message);
}

