const data = $input.first().json;

const PROMPT = `# DOCUMENT SUMMARY EXTRACTION

You are a document analyst. Extract structured information from business documents and meeting notes.

## OUTPUT FORMAT

Return ONLY a raw JSON object with exactly two keys:

{
  "document_summary": "A 3-5 sentence narrative of the main topics, decisions, and outcomes",
  "ai_observations": {
    "key_themes": ["theme1", "theme2"],
    "action_items": ["action1", "action2"],
    "decisions_made": ["decision1"],
    "participants": ["name1", "name2"],
    "sentiment": "positive|neutral|concerns_raised|mixed"
  }
}

Do not wrap the output in triple backticks. Do not include any text before or after the JSON object.

## TASK

Extract a structured summary from the document below.

Rules:
- document_summary: 3-5 sentences covering main topics, key decisions, and outcomes
- ai_observations: metadata extracted directly from the document
- If information is absent or unclear, use empty string or empty array - never fabricate
- Return exactly two keys: document_summary and ai_observations

<document>
$raw_file_content
</document>`;

const rawContent = typeof data.raw_content === 'string'
  ? data.raw_content
  : JSON.stringify(data.raw_content);

// Truncate very large documents to prevent timeout
const MAX_CHARS = 100000;
let content = rawContent;
let truncated = false;
if (content.length > MAX_CHARS) {
  content = content.slice(0, MAX_CHARS);
  truncated = true;
}

const truncationNote = truncated
  ? 'Note: This document was truncated from ' + rawContent.length + ' to ' + MAX_CHARS + ' characters. Extract what is available and flag any sections that appear incomplete.\n\n'
  : '';

const prompt = JSON.stringify(PROMPT.replace('$raw_file_content', truncationNote + content));

return [{
  prompt: prompt,
  model: 'global.anthropic.claude-haiku-4-5-20251001-v1:0',
  node_name: 'DSE: Format Extraction Prompt',
  workflow_session_id: $execution.id,
  workflow_id: $workflow.id,
  client_id: 'client_' + data.client_id,
  project_id: 'project_' + data.project_id,
  file_type: data.file_type,
  meeting_note_id: data.meeting_note_id,
  project_document_id: data.project_document_id
}];

